package cn.buwei.nativeapp.features

import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import cn.buwei.nativeapp.data.ClientRepository
import kotlinx.coroutines.CancellationException
import kotlinx.serialization.json.*

@Composable internal fun TaskWorkspacePlanning(repository:ClientRepository,base:String,graph:JsonObject,me:JsonObject,members:List<JsonObject>,onChanged:()->Unit){
 var refresh by remember{mutableIntStateOf(0)};var feedback by remember{mutableStateOf<JsonObject?>(null)};var brief by rememberSaveable{mutableStateOf("")};var feedbackDraft by remember{mutableStateOf("")};var sources by remember{mutableStateOf<List<JsonObject>>(emptyList())};var materials by remember{mutableStateOf<List<JsonObject>>(emptyList())};var sourceIds by remember{mutableStateOf<List<String>>(emptyList())};var materialIds by remember{mutableStateOf<List<String>>(emptyList())};var selectedTasks by remember{mutableStateOf<List<String>>(emptyList())};var action by rememberSaveable{mutableStateOf("adjust")};var search by rememberSaveable{mutableStateOf(false)};var searchQuery by rememberSaveable{mutableStateOf("")};var job by remember{mutableStateOf<String?>(null)};var error by remember{mutableStateOf<String?>(null)}
 LaunchedEffect(base,repository.accountId){try{feedback=repository.get("$base/collaboration/feedback/current");feedbackDraft=feedback!!.twText("feedback");sources=taskWorkspaceAllPages(repository,"$base/sources");materials=taskWorkspaceAllPages(repository,"$base/materials");job=repository.get("$base/collaboration/ai-activity").twText("jobId").takeIf{it.isNotBlank()};error=null}catch(e:CancellationException){throw e}catch(e:Exception){error=e.message}}
 Text("AI 拆解、调整与分工",style=MaterialTheme.typography.titleLarge);error?.let{Text(it,color=MaterialTheme.colorScheme.error)}
 if(me.twText("role")=="owner"&&feedback!=null){TaskWorkspaceField("持续项目反馈",feedbackDraft,{feedbackDraft=it},12000,3,aiReference=true);TaskWorkspaceAction(repository,"保存项目反馈","$base/collaboration/feedback/current",buildJsonObject{put("expectedVersion",feedback!!["version"]!!);put("feedback",feedbackDraft)},onSuccess={feedback=it;refresh++})}else feedback?.let{NativeMarkdown(it.twText("feedback"))}
 TaskProjectFeedbackHistory(repository,base,refresh,members)
 if(me.twCan("taskManage")){
 TaskWorkspaceChoice("AI 操作",listOf("decompose" to "重新拆解全部任务","adjust" to "调整选中任务","assign" to "建议分工"),action){action=it;selectedTasks=emptyList()}
 if(action!="decompose"){Text("选择任务范围");graph.twRows().filter{if(action=="assign")it.twText("assigneeId").isBlank()&&it.twText("lifecycleState")=="open"else it.twText("lifecycleState") in listOf("open","in_progress","improve","rework")}.forEach{task->val id=task.twText("taskId");Row{Checkbox(id in selectedTasks,{checked->selectedTasks=if(checked)selectedTasks+id else selectedTasks-id});Text(task.twText("title"),Modifier.padding(top=12.dp))}}}
 if(action!="assign"){TaskWorkspaceField("本次要求",brief,{brief=it},12000,3,aiReference=true);Text("固定引用的资料版本（可选）");sources.filter{it.twText("currentVersionId").isNotBlank()}.forEach{source->val id=source.twText("currentVersionId");Row{Checkbox(id in sourceIds,{checked->sourceIds=if(checked)sourceIds+id else sourceIds-id});Text(source.twText("title"),Modifier.padding(top=12.dp))}};Text("固定引用的成果版本（最多 10 项）");materials.filter{it.twText("currentVersionId").isNotBlank()}.forEach{material->val id=material.twText("currentVersionId");Row{Checkbox(id in materialIds,{checked->if(!checked||materialIds.size<10)materialIds=if(checked)materialIds+id else materialIds-id});Text(material.twText("title"),Modifier.padding(top=12.dp))}};Row{Checkbox(search,{search=it});Text("允许项目配置的联网搜索",Modifier.padding(top=12.dp))};if(search)TaskWorkspaceField("搜索问题",searchQuery,{searchQuery=it},500,aiReference=true)}
 val body=buildJsonObject{if(action=="assign")put("taskIds",JsonArray(selectedTasks.map{JsonPrimitive(it)}))else{put("brief",brief.trim());if(action=="adjust")put("taskIds",JsonArray(selectedTasks.map{JsonPrimitive(it)}));if(sourceIds.isNotEmpty())put("sourceVersionIds",JsonArray(sourceIds.map{JsonPrimitive(it)}));if(materialIds.isNotEmpty())put("materialVersionIds",JsonArray(materialIds.map{JsonPrimitive(it)}));put("allowSearch",search);if(search)put("searchQuery",searchQuery.trim())}}
 TaskWorkspaceAction(repository,"请求 AI 建议","$base/collaboration/${if(action=="assign")"assign"else"decompose"}",body,enabled=(action!="decompose"||graph["canRegenerate"]?.jsonPrimitive?.booleanOrNull==true)&&(action=="decompose"||selectedTasks.isNotEmpty())&&(action=="assign"||brief.isNotBlank()&&(!search||searchQuery.isNotBlank())),confirmation="将调用已配置的 AI，可能产生费用；请先保存需要使用的项目反馈。建议需按项目规则确认后才能应用。",onSuccess={job=it.twText("jobId").takeIf{value->value.isNotBlank()}})
 }
 job?.let{NativeJobExecution(repository,it){refresh++;onChanged()}}
 Text("AI 建议与历史",style=MaterialTheme.typography.titleMedium);TaskWorkspacePage(repository,"$base/collaboration/proposals?limit=50",refresh){rows->rows.forEach{proposal->TaskWorkspaceProposal(repository,base,proposal,graph.twRows(),members,me.twCan("taskManage")){refresh++;onChanged()}}}
}
@Composable private fun TaskWorkspaceProposal(repository:ClientRepository,base:String,proposal:JsonObject,tasks:List<JsonObject>,members:List<JsonObject>,manage:Boolean,onChanged:()->Unit){
 val payload=proposal["payload"] as? JsonObject?:JsonObject(emptyMap());var expanded by remember{mutableStateOf(false)};Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){
 Text((if(proposal.twText("kind")=="assign")"分工建议"else"任务拆解与调整建议")+" · "+mapOf("pending" to "待确认","applied" to "已应用","stale" to "已过期")[proposal.twText("status")]);Text(proposal.twText("createdAt"));OutlinedButton({expanded=!expanded}){Text(if(expanded)"收起建议"else"查看建议")}
 if(expanded){payload.twRows("tasks").forEach{Text(it.twText("title"),style=MaterialTheme.typography.titleMedium);val parent=it.twText("parent");if(parent.isNotBlank())Text("父任务："+(payload.twRows("tasks").firstOrNull{row->row.twText("key")==parent}?.twText("title")?:tasks.firstOrNull{row->row.twText("taskId")==parent}?.twText("title")?:"暂不可见任务"));NativeMarkdown(it.twText("detail"));Text("验收标准：${it.twText("criteria")} · ${it.twText("effortHours")} 小时");val keys=it.twIds("dependsOn");if(keys.isNotEmpty())Text("前置任务："+keys.joinToString("、"){id->payload.twRows("tasks").firstOrNull{row->row.twText("key")==id}?.twText("title")?:"不可见任务"})};payload.twRows("updates").forEach{Text("调整：${it.twText("title")}");if("parentTaskId" in it)Text("父任务："+(tasks.firstOrNull{row->row.twText("taskId")==it.twText("parentTaskId")}?.twText("title")?:"无父任务"));NativeMarkdown(it.twText("detail"));Text("验收标准：${it.twText("criteria")}")};payload.twRows("assignments").forEach{Text((tasks.firstOrNull{task->task.twText("taskId")==it.twText("taskId")}?.twText("title")?:"不可见任务")+" → "+(members.firstOrNull{member->member.twText("userId")==it.twText("assigneeId")}?.twText("displayName")?:"未分配"));NativeMarkdown(it.twText("reason"))};payload.twIds("considerations").forEach{NativeMarkdown(it)}
 if(manage)TaskProposalControls(repository,base,proposal,tasks,members,onChanged)
 }
 }}
}
